xml.Script:
        clYellow       := 'FFFF00';
        clBlue         := '0000A0';
        clViolett      := '800080';
        clRed          := 'FF0000';
        clGreen        := '008000';
        clOrange       := 'FF6000';
        clLightBlue    := '2828FF';
        clLightViolett := 'FF0080';
        clBrown        := '800000';
        clLightGreen   := '00FF00';

        R := 0.5;
        C0 := R * sqrt(5 * (5 - 2 * sqrt(5))) / 5;
        C1 := R * (sqrt(5) - 1) / 2;
        C2 := R * sqrt(10 * (5 + sqrt(5))) / 10;
        C3 := R * sqrt(10 * (5 - sqrt(5))) / 5;
        C4 := R * (5 + sqrt(5)) / 5;

        for i := 0 to 4 do begin
            ax[i] := sin(2*Pi/5 * i);
            ay[i] := cos(2*Pi/5 * i);
        end;
        az := sqrt((1 - cos(2*Pi/5)) / 2);

        D  := (C2 - C0) / 2 / sqrt(1 + az^2);

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          vx := y1 * z2 - y2 * z1;
          vy := z1 * x2 - z2 * x1;
          vz := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((vx*wx + vy*wy + vz*wz) / (vx^2 + vy^2 + vz^2));
        end;

        A1 := Angle(ax[0], ay[0], az, ax[2], ay[2],  az, ax[3], ay[3], az);
        A2 := Angle(ax[0], ay[0], az, ax[0], ay[0], -az, ax[1], ay[1], az);
        A3 := Angle(ax[0], ay[0], az, ax[1], ay[1],  az, ax[4], ay[4], az);
